node -e '
const fs = require("fs");
const specs = ["specs/hal-engine-config-hooks/spec.md","specs/hal-engine-tool-input-validation/spec.md"];
const files = {};
const read = p => (files[p] ??= fs.readFileSync(p, "utf8").split("\n"));
let bad = 0;
for (const spec of specs) {
  const text = read(spec).join("\n");
  for (const m of text.matchAll(/\[validated by: ([^\]]+)\]\(([^)#]+\.test\.ts)#L(\d+)\)/g)) {
    const [, title, path, lineStr] = m;
    const line = read(path)[Number(lineStr) - 1] ?? "";
    const ok = line.includes(`it(\x27${title}\x27`) || line.includes(`describe(\x27${title}\x27`);
    if (!ok) { bad++; console.log(`MISMATCH ${path}#L${lineStr}: ${title}\n  line: ${line.trim().slice(0,90)}`); }
  }
}
console.log(bad === 0 ? "all anchors land on their cited test titles" : bad + " mismatches");'

node -e '
const fs = require("fs");
const path = require("path");
const specs = ["specs/hal-engine-config-hooks/spec.md","specs/hal-engine-tool-input-validation/spec.md"];
const files = {};
const read = p => (files[p] ??= fs.readFileSync(p, "utf8").split("\n"));
let bad = 0, n = 0;
for (const spec of specs) {
  const dir = path.dirname(spec);
  const text = read(spec).join("\n");
  for (const m of text.matchAll(/\[validated by: ([^\]]+)\]\(([^)#]+\.test\.ts)#L(\d+)\)/g)) {
    const [, title, rel, lineStr] = m;
    const p = path.join(dir, rel);
    const line = read(p)[Number(lineStr) - 1] ?? "";
    n++;
    const ok = line.includes(`it(\x27${title}\x27`) || line.includes(`describe(\x27${title}\x27`);
    if (!ok) { bad++; console.log(`MISMATCH ${p}#L${lineStr}: ${title}\n  line: ${line.trim().slice(0,90)}`); }
  }
}
console.log(`${n} anchors checked, ${bad} mismatches`);'
